import{_ as s,o as a,c as i,a0 as n}from"./chunks/framework.t4Rf69I2.js";const g=JSON.parse('{"title":"CI/CD Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/ci-cd.md","filePath":"en/guide/ci-cd.md","lastUpdated":1785233645000}'),t={name:"en/guide/ci-cd.md"};function l(p,e,o,r,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="ci-cd-pipeline" tabindex="-1">CI/CD Pipeline <a class="header-anchor" href="#ci-cd-pipeline" aria-label="Permalink to &quot;CI/CD Pipeline&quot;">​</a></h1><p>go-cipher-cli uses <strong>GitHub Actions</strong> for fully automated releases. When you push a tag in <code>v*</code> format (e.g. <code>v0.1.0</code>), the pipeline automatically completes the entire process of compiling, packaging, signing, documentation building, and deployment.</p><p>The workflow definition is in <a href="https://github.com/kulaiyin/go-cipher-cli/blob/main/.github/workflows/release.yml" target="_blank" rel="noreferrer"><code>.github/workflows/release.yml</code></a>.</p><h2 id="trigger-conditions" tabindex="-1">Trigger Conditions <a class="header-anchor" href="#trigger-conditions" aria-label="Permalink to &quot;Trigger Conditions&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;v*&#39;</span></span></code></pre></div><p>That is, any tag push in the form of <code>v0.1.0</code>, <code>v1.2.3</code> will trigger it.</p><h2 id="pipeline-steps" tabindex="-1">Pipeline Steps <a class="header-anchor" href="#pipeline-steps" aria-label="Permalink to &quot;Pipeline Steps&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  push v* tag                                                    │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  1. Checkout (fetch-depth: 0, goreleaser needs full history)    │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  2. Set up the Go environment                                   │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  3. Set up the Node environment (VitePress build)               │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  4. goreleaser release (official goreleaser-action)             │</span></span>
<span class="line"><span>│     ├─ Compile the linux/amd64 binary                           │</span></span>
<span class="line"><span>│     ├─ Generate the .deb                                        │</span></span>
<span class="line"><span>│     └─ Create the GitHub Release, upload .deb / tar.gz / checksums │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  5. Import the GPG private key (decoded from Secret GPG_SIGNING_KEY) │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  6. Run scripts/publish_repo.sh                                 │</span></span>
<span class="line"><span>│     ├─ Generate dists/ pool/ Release InRelease                  │</span></span>
<span class="line"><span>│     └─ Sign with the imported key                               │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  7. Export the GPG public key to repo/repo.gpg.key              │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  8. Build the VitePress documentation site (npm ci &amp;&amp; npm run docs:build) │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  9. Aggregate deployment content (docs + APT repository)        │</span></span>
<span class="line"><span>│      │                                                          │</span></span>
<span class="line"><span>│      ▼                                                          │</span></span>
<span class="line"><span>│  10. Deploy to the gh-pages branch                              │</span></span>
<span class="line"><span>│      ├─ Documentation site → root path                          │</span></span>
<span class="line"><span>│      └─ APT repository (repo/) → /apt subpath                   │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="release-version-number" tabindex="-1">Release Version Number <a class="header-anchor" href="#release-version-number" aria-label="Permalink to &quot;Release Version Number&quot;">​</a></h2><p>The version number comes from the <strong>git tag</strong>:</p><ul><li>tag <code>v0.1.0</code> → goreleaser produces <code>go-cipher-cli_0.1.0_linux_amd64.deb</code></li><li>The version is also written into the APT repository&#39;s <code>Packages</code> index</li></ul><p>Therefore, the only action required for a release is to push a tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Everything after this is fully automatic, no intervention needed</span></span></code></pre></div><h2 id="signing-key-management" tabindex="-1">Signing Key Management <a class="header-anchor" href="#signing-key-management" aria-label="Permalink to &quot;Signing Key Management&quot;">​</a></h2><p>The GPG private key is injected via a <strong>GitHub Repository Secret</strong>; the private key itself never enters the codebase.</p><h3 id="generate-or-reuse-a-gpg-key" tabindex="-1">Generate or Reuse a GPG Key <a class="header-anchor" href="#generate-or-reuse-a-gpg-key" aria-label="Permalink to &quot;Generate or Reuse a GPG Key&quot;">​</a></h3><p>Generate locally (or reuse an existing one):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gen-key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Note the generated Key ID, e.g. 9E38A2B39666B218</span></span></code></pre></div><h3 id="export-the-private-key-and-base64-encode-it" tabindex="-1">Export the Private Key and Base64 Encode It <a class="header-anchor" href="#export-the-private-key-and-base64-encode-it" aria-label="Permalink to &quot;Export the Private Key and Base64 Encode It&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --armor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export-secret-keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9E38A2B39666B218</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w0</span></span></code></pre></div><p><code>base64 -w0</code> outputs a single line, avoiding newlines in the Secret that would cause import failures.</p><h3 id="configure-the-github-secret" tabindex="-1">Configure the GitHub Secret <a class="header-anchor" href="#configure-the-github-secret" aria-label="Permalink to &quot;Configure the GitHub Secret&quot;">​</a></h3><ol><li>Open <code>https://github.com/kulaiyin/go-cipher-cli/settings/secrets/actions</code> in your browser</li><li>Click <code>New repository secret</code></li><li><strong>Name</strong>: <code>GPG_SIGNING_KEY</code></li><li><strong>Value</strong>: paste the base64 output from the previous step</li><li>Save</li></ol><p>Also ensure that the <code>SignWith:</code> in <code>repo/conf/distributions</code> matches this Key ID (currently <code>9E38A2B39666B218</code>). The CI <code>publish_repo.sh</code> reads this value automatically and signs with the imported private key.</p><div class="warning custom-block"><p class="custom-block-title">Private Key Security</p><p>If the private key is leaked, anyone can forge your repository signature. Please:</p><ul><li>Store it only in the GitHub Secret, never write it to any file or log</li><li>Rotate it periodically (generate a new key, update the Secret, republish once so clients import the new public key)</li></ul></div><h3 id="rotating-keys" tabindex="-1">Rotating Keys <a class="header-anchor" href="#rotating-keys" aria-label="Permalink to &quot;Rotating Keys&quot;">​</a></h3><ol><li>Generate a new key locally.</li><li>Update the <code>SignWith:</code> in <code>repo/conf/distributions</code> to the new Key ID.</li><li>Update the GitHub Secret <code>GPG_SIGNING_KEY</code>.</li><li>Trigger a release again; <code>repo.gpg.key</code> will be automatically updated to the new public key.</li><li>Notify clients to re-run the public key import step (<code>curl ... | sudo gpg --dearmor</code>).</li></ol><h2 id="enabling-github-pages-first-deployment" tabindex="-1">Enabling GitHub Pages (First Deployment) <a class="header-anchor" href="#enabling-github-pages-first-deployment" aria-label="Permalink to &quot;Enabling GitHub Pages (First Deployment)&quot;">​</a></h2><p>After the first successful release, the <code>gh-pages</code> branch will be created. You need to enable Pages in the repository settings:</p><ol><li>Open <code>https://github.com/kulaiyin/go-cipher-cli/settings/pages</code> in your browser</li><li><strong>Source</strong> → select <code>Deploy from a branch</code></li><li><strong>Branch</strong> → select <code>gh-pages</code>, directory <code>/ (root)</code></li><li>Save</li></ol><p>Within a few minutes, <code>https://kulaiyin.github.io/go-cipher-cli/</code> will be accessible.</p><h2 id="previewing-release-artifacts-locally" tabindex="-1">Previewing Release Artifacts Locally <a class="header-anchor" href="#previewing-release-artifacts-locally" aria-label="Permalink to &quot;Previewing Release Artifacts Locally&quot;">​</a></h2><p>No need to actually push a tag — the whole process can be reproduced locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/package.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Generate the APT repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish_repo.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Preview the documentation site locally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><strong><code>goreleaser: command not found</code></strong>: CI uses the official <code>goreleaser-action</code> and requires no manual installation; locally you can run <code>go install github.com/goreleaser/goreleaser@latest</code>.</li><li><strong><code>reprepro: command not found</code></strong>: <code>publish_repo.sh</code> will automatically fall back to apt-ftparchive; see Approach C in <a href="./apt-repo">APT Repository and GitHub Pages</a>.</li><li><strong>Signing failure / <code>InRelease</code> error</strong>: First generate a key with <code>gpg --gen-key</code>, and set <code>SignWith:</code> in <code>repo/conf/distributions</code> to the real Key ID.</li><li><strong>Signing failure in CI</strong>: Check whether the Secret <code>GPG_SIGNING_KEY</code> is configured, whether it is in <code>base64 -w0</code> single-line format, and whether <code>SignWith</code> is consistent.</li><li><strong>Client <code>NO_PUBKEY</code> error</strong>: The publisher&#39;s public key was not imported correctly, or the public key has been rotated; re-import it per the <a href="./installation">Installation guide</a>.</li><li><strong>Client <code>Could not handshake</code> / connection reset</strong>: Usually because <code>*.github.io</code> is being interfered with by the network (e.g. GFW). Configure a proxy for apt, switch to the jsDelivr CDN mirror, or download the <code>.deb</code> directly from GitHub Release and install manually.</li><li><strong>gh-pages not updating</strong>: Pages is not enabled or the wrong branch is selected. Confirm <code>gh-pages</code> is selected in Settings → Pages.</li></ul>`,36)])])}const u=s(t,[["render",l]]);export{g as __pageData,u as default};
